export const byPlacement = (p: MediaItem['placements'][number]) =>
  media.filter((m) => m.placements.includes(p)).sort((a, b) => a.order - b.order);

export const byId = (id: string) => {
  const m = media.find((x) => x.id === id);
  if (!m) throw new Error(`Unknown media id: ${id}`);
  return m;
};
